"use client";
import { ArrowUp, Paperclip, Square } from "lucide-react";
import { useRef } from "react";
import { Textarea } from "@/components/ui/textarea";
import { Select } from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
export type AIComposerLabels = {
  placeholder: string;
  input: string;
  send: string;
  stop: string;
  model: string;
  attach: string;
  balanced: string;
  precise: string;
  creative: string;
  attached: string;
};
export function AIComposer({
  prompt,
  onPromptChange,
  onSend,
  onCancel,
  pending,
  model,
  onModelChange,
  labels,
  className,
  onAttach,
}: {
  prompt: string;
  onPromptChange: (value: string) => void;
  onSend: () => void;
  onCancel: () => void;
  pending: boolean;
  model: string;
  onModelChange: (value: string) => void;
  labels: AIComposerLabels;
  className?: string;
  onAttach?: (file: File) => void;
}) {
  const fileInput = useRef<HTMLInputElement>(null);
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (prompt.trim() && !pending) onSend();
      }}
      className={cn(
        "af-card af-shadow-elevated relative isolate overflow-hidden rounded-xl border border-border bg-surface p-3 transition-[border-color,box-shadow] focus-within:border-primary/60 focus-within:ring-2 focus-within:ring-primary/15 sm:p-4",
        className,
      )}
    >
      <span
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-0 top-0 h-px opacity-75"
        style={{ background: "var(--af-gradient-text)" }}
      />
      <Textarea
        aria-label={labels.input}
        placeholder={labels.placeholder}
        value={prompt}
        maxLength={4000}
        onChange={(e) => onPromptChange(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
            e.preventDefault();
            if (!pending && prompt.trim()) onSend();
          }
        }}
        className="min-h-24 resize-none border-0 bg-transparent px-2 text-sm leading-7 shadow-none hover:border-transparent focus-visible:ring-0"
      />
      <div className="mt-3 flex items-center justify-between gap-2 border-t border-border/65 pt-3">
        <div className="flex min-w-0 items-center gap-2">
          <Select
            value={model}
            onValueChange={onModelChange}
            aria-label={labels.model}
            options={[
              { value: "balanced", label: labels.balanced },
              { value: "precise", label: labels.precise },
              { value: "creative", label: labels.creative },
            ]}
            className="h-9 w-[min(190px,44vw)] bg-surface-subtle/65 text-[13px]"
          />
          {onAttach && (
            <>
              <Button
                type="button"
                aria-label={labels.attach}
                variant="ghost"
                size="icon-sm"
                onClick={() => fileInput.current?.click()}
              >
                <Paperclip aria-hidden="true" />
              </Button>
              <input
                ref={fileInput}
                type="file"
                accept=".txt,.md,.csv,.json"
                className="sr-only"
                tabIndex={-1}
                aria-label={labels.attach}
                onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) onAttach(file);
                  e.target.value = "";
                }}
              />
            </>
          )}
        </div>
        {pending ? (
          <Button type="button" size="sm" variant="outline" onClick={onCancel}>
            <Square className="size-3!" aria-hidden="true" />
            {labels.stop}
          </Button>
        ) : (
          <Button
            type="submit"
            size="icon"
            appearance="gradient"
            aria-label={labels.send}
            disabled={!prompt.trim()}
          >
            <ArrowUp aria-hidden="true" />
          </Button>
        )}
      </div>
    </form>
  );
}

"use client";
import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";
import { LoaderCircle } from "lucide-react";
import { cn } from "@/lib/utils";
import "@/styles/effects.css";

export const buttonVariants = cva(
  "af-button af-control inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap border border-transparent text-[13px] leading-5 font-semibold tracking-[-.01em] outline-none transition-[background-color,border-color,color,box-shadow,transform] duration-[var(--af-motion-fast,150ms)] active:scale-[.98] motion-reduce:transform-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:pointer-events-none disabled:opacity-45 data-disabled:pointer-events-none data-disabled:opacity-45 [@media(pointer:coarse)]:min-h-11 [@media(pointer:coarse)]:min-w-11 [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default:
          "af-button-primary bg-primary text-primary-foreground hover:bg-[color:var(--af-shade-primary,var(--primary-hover))]",
        outline:
          "af-button-outline border-border bg-surface text-foreground [background-image:none] hover:border-primary/40 hover:bg-[color:var(--af-shade-outline,var(--surface-subtle))]",
        secondary:
          "af-button-surface bg-accent text-accent-foreground [background-image:none] hover:bg-[color:var(--af-shade-surface,var(--accent))] hover:text-foreground",
        ghost:
          "bg-transparent text-muted-foreground hover:bg-surface-subtle hover:text-foreground",
        destructive:
          "af-button-destructive bg-destructive text-destructive-foreground [background-image:none] hover:bg-[color:var(--af-shade-destructive,var(--destructive))]",
        link: "af-hover-link bg-transparent text-primary underline underline-offset-4 hover:text-primary-hover",
      },
      size: {
        sm: "h-8 px-3",
        default: "h-[var(--af-control-height,40px)] px-4",
        lg: "h-12 px-6 text-sm",
        icon: "size-[var(--af-control-height,40px)]",
        "icon-sm": "size-8",
      },
      shape: {
        rounded: "rounded-[var(--radius-md,10px)]",
        pill: "rounded-full",
        square: "rounded-none",
      },
    },
    defaultVariants: { variant: "default", size: "default", shape: "rounded" },
  },
);
export type ButtonShape = "rounded" | "pill" | "square";
export type ButtonAppearance =
  "solid" | "soft" | "outline" | "glass" | "gradient";
const appearanceClasses: Record<ButtonAppearance, string> = {
  solid: "[background-image:none]",
  soft: "border-primary/25 bg-accent text-accent-foreground [background-image:none] hover:bg-[color:var(--af-shade-surface)] hover:text-foreground",
  outline:
    "border-primary/40 bg-surface text-foreground [background-image:none] hover:bg-[color:var(--af-shade-outline)] hover:text-foreground",
  glass:
    "border-primary/30 bg-[var(--af-glass-background)] text-foreground hover:bg-[var(--af-glass-background)] hover:text-foreground",
  gradient:
    "border-transparent bg-primary text-primary-foreground [background-image:var(--af-gradient-primary)] hover:bg-primary-hover hover:text-primary-foreground",
};
export type ButtonProps = Omit<
  React.ComponentProps<typeof ButtonPrimitive>,
  "className"
> &
  VariantProps<typeof buttonVariants> & {
    className?: string;
    loading?: boolean;
    appearance?: ButtonAppearance;
  };
export function Button({
  className,
  variant,
  size,
  shape,
  loading,
  appearance,
  children,
  disabled,
  focusableWhenDisabled,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  "aria-busy": ariaBusy,
  ...props
}: ButtonProps) {
  const labelId = React.useId();
  return (
    <ButtonPrimitive
      {...props}
      data-slot="button"
      data-variant={variant ?? "default"}
      data-size={size ?? "default"}
      data-shape={shape ?? "rounded"}
      data-appearance={appearance}
      className={cn(
        buttonVariants({ variant, size, shape }),
        appearance && `af-control-${appearance}`,
        appearance &&
          variant !== "destructive" &&
          appearanceClasses[appearance],
        className,
      )}
      disabled={disabled || loading}
      focusableWhenDisabled={focusableWhenDisabled ?? loading}
      aria-busy={loading || ariaBusy}
      aria-label={ariaLabel}
      aria-labelledby={
        ariaLabelledBy ?? (loading && !ariaLabel ? labelId : undefined)
      }
    >
      {loading && (
        <LoaderCircle
          className="motion-safe:animate-spin motion-reduce:animate-none [[data-motion-level=off]_&]:animate-none"
          aria-hidden="true"
        />
      )}
      <span id={labelId} className="contents">
        {children}
      </span>
    </ButtonPrimitive>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";
export const inputClasses =
  "af-input flex h-[var(--af-control-height,40px)] w-full min-w-0 rounded-[var(--radius-md,10px)] border border-border bg-surface px-3.5 text-[13px] leading-6 text-foreground outline-none transition-[border-color,background-color,box-shadow] placeholder:text-muted-foreground hover:border-primary/35 focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/25 aria-invalid:border-destructive-foreground aria-invalid:ring-destructive-foreground/20 disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:border-border file:mr-3 file:rounded-md file:border-0 file:bg-accent file:px-2 file:py-1 file:text-xs file:font-semibold file:text-accent-foreground";
export function Input({ className, ...props }: React.ComponentProps<"input">) {
  return (
    <input
      data-slot="input"
      className={cn(inputClasses, className)}
      {...props}
    />
  );
}

"use client";
import type { ReactNode } from "react";
import { Select as SelectPrimitive } from "@base-ui/react/select";
import { Check, ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";
import { inputClasses } from "@/components/ui/input";
export type SelectOption = {
  value: string;
  label: string;
  disabled?: boolean;
  icon?: ReactNode;
};
export type SelectProps = {
  options: SelectOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  label?: string;
  name?: string;
  id?: string;
  disabled?: boolean;
  className?: string;
  "aria-label"?: string;
  "aria-labelledby"?: string;
  "aria-describedby"?: string;
  "aria-invalid"?: boolean;
};
export function Select({
  options,
  value,
  defaultValue,
  onValueChange,
  placeholder,
  label,
  className,
  name,
  disabled,
  ...aria
}: SelectProps) {
  return (
    <SelectPrimitive.Root
      items={options}
      value={value}
      defaultValue={defaultValue}
      name={name}
      disabled={disabled}
      onValueChange={(v) => {
        if (v !== null) onValueChange?.(v);
      }}
    >
      {label && (
        <SelectPrimitive.Label className="mb-2 block text-xs font-semibold">
          {label}
        </SelectPrimitive.Label>
      )}
      <SelectPrimitive.Trigger
        className={cn(
          inputClasses,
          "items-center justify-between gap-3",
          className,
        )}
        {...aria}
      >
        <SelectPrimitive.Value
          placeholder={placeholder}
          className="min-w-0 truncate whitespace-nowrap"
        >
          {options.some((option) => option.icon)
            ? (selectedValue: string | null) => {
                const selected = options.find(
                  (option) => option.value === selectedValue,
                );
                if (!selected) return placeholder;
                return (
                  <span className="flex min-w-0 items-center gap-2">
                    {selected.icon}
                    <span className="truncate">{selected.label}</span>
                  </span>
                );
              }
            : undefined}
        </SelectPrimitive.Value>
        <SelectPrimitive.Icon>
          <ChevronDown className="size-3.5 opacity-60" />
        </SelectPrimitive.Icon>
      </SelectPrimitive.Trigger>
      <SelectPrimitive.Portal>
        <SelectPrimitive.Positioner
          sideOffset={6}
          alignItemWithTrigger={false}
          className="z-70"
        >
          <SelectPrimitive.Popup className="min-w-(--anchor-width) max-h-80 overflow-auto rounded-lg border border-border bg-surface p-1 text-[13px] text-foreground shadow-lg">
            <SelectPrimitive.List>
              {options.map((option) => (
                <SelectPrimitive.Item
                  key={option.value}
                  value={option.value}
                  disabled={option.disabled}
                  className="flex cursor-default items-center justify-between gap-6 rounded-md px-3 py-2 outline-none data-highlighted:bg-accent data-disabled:opacity-40"
                >
                  <SelectPrimitive.ItemText>
                    <span className="flex items-center gap-2">
                      {option.icon}
                      <span>{option.label}</span>
                    </span>
                  </SelectPrimitive.ItemText>
                  <SelectPrimitive.ItemIndicator>
                    <Check className="size-3.5" />
                  </SelectPrimitive.ItemIndicator>
                </SelectPrimitive.Item>
              ))}
            </SelectPrimitive.List>
          </SelectPrimitive.Popup>
        </SelectPrimitive.Positioner>
      </SelectPrimitive.Portal>
    </SelectPrimitive.Root>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";
import { inputClasses } from "@/components/ui/input";
export function Textarea({
  className,
  ...props
}: React.ComponentProps<"textarea">) {
  return (
    <textarea
      data-slot="textarea"
      className={cn(
        inputClasses,
        "af-textarea min-h-28 resize-y py-3 leading-7",
        className,
      )}
      {...props}
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
export function downloadText(
  filename: string,
  text: string,
  type = "text/plain",
) {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function csv(rows: Record<string, unknown>[]) {
  if (!rows.length) return "";
  const keys = Object.keys(rows[0]);
  const escape = (value: unknown) => {
    const raw = String(value ?? "");
    const safe = /^[=+@\t\r-]/.test(raw) ? `'${raw}` : raw;
    return `"${safe.replaceAll('"', '""')}"`;
  };
  return [
    keys.map(escape).join(","),
    ...rows.map((row) => keys.map((k) => escape(row[k])).join(",")),
  ].join("\r\n");
}

/*
 * Aureform effects. Import after the generated tokens.css in globals.css.
 * Component-layer rules allow Tailwind utilities to override decoration.
 * Shadow composition retains Tailwind 4 focus rings.
 */
@layer components {
  .af-surface-gradient {
    background-color: var(--surface);
    background-image: var(--af-gradient-surface);
  }

  .af-hero-gradient {
    background-color: var(--background);
    background-image: var(--af-gradient-hero);
  }

  .af-shadow-soft {
    --tw-shadow: var(--af-shadow-soft);
  }

  .af-shadow-elevated {
    --tw-shadow: var(--af-hover-shadow, var(--af-shadow-elevated));
  }

  .af-shadow-floating {
    --tw-shadow: var(--af-shadow-floating);
  }

  .af-shadow-soft,
  .af-shadow-elevated,
  .af-shadow-floating,
  .af-hover-card,
  .af-button {
    box-shadow:
      var(--tw-inset-shadow, 0 0 #0000), var(--tw-inset-ring-shadow, 0 0 #0000),
      var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000),
      var(--tw-shadow, 0 0 #0000);
  }

  .af-button {
    transition:
      background-color var(--af-motion-fast) var(--af-motion-easing),
      border-color var(--af-motion-fast) var(--af-motion-easing),
      color var(--af-motion-fast) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing);
  }

  .af-button-primary,
  .af-button-outline,
  .af-button-surface,
  .af-button-destructive {
    background-image: var(--af-gradient-control);
  }

  .af-button-primary,
  .af-button-surface,
  .af-button-destructive {
    --tw-shadow: var(--af-shadow-soft);
  }

  .af-hover-card {
    transition:
      background-color var(--af-motion-fast) var(--af-motion-easing),
      border-color var(--af-motion-fast) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing),
      transform var(--af-motion-hover) var(--af-motion-easing);
  }

  .af-hover-link {
    color: var(--primary);
    text-decoration-line: underline;
    text-decoration-color: color-mix(in srgb, var(--primary) 45%, transparent);
    text-decoration-thickness: 1px;
    text-underline-offset: 0.22em;
    transition:
      color var(--af-motion-fast) var(--af-motion-easing),
      text-decoration-color var(--af-motion-fast) var(--af-motion-easing);
  }

  .af-hover-link:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):focus-visible {
    color: var(--primary-hover);
    text-decoration-color: currentColor;
    text-decoration-thickness: 2px;
    outline: 2px solid var(--ring);
    outline-offset: 3px;
  }

  @media (hover: hover) and (pointer: fine) {
    .af-button-outline:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      --tw-shadow: var(--af-shadow-soft);
    }

    .af-hover-link:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      color: var(--primary-hover);
      text-decoration-color: currentColor;
      text-decoration-thickness: 2px;
    }
  }

  .af-button:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):active {
    --tw-shadow: 0 0 #0000;
  }

  .af-button:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-card:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-link:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
    cursor: default;
    pointer-events: none;
    animation: none;
    transition: none;
    transform: none;
    translate: none;
  }

  .af-button:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
    --tw-shadow: 0 0 #0000;
    background-image: none;
  }
}

/* Interactive state colors must take precedence over a base bg-surface utility. */
@layer utilities {
  .af-hover-card:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):focus-visible {
    --tw-shadow: var(--af-shadow-elevated);
    background-color: var(--af-shade-card);
    outline: 2px solid var(--ring);
    outline-offset: 3px;
    transform: translateY(var(--af-motion-lift));
  }

  @media (hover: hover) and (pointer: fine) {
    .af-hover-card:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      --tw-shadow: var(--af-hover-shadow, var(--af-shadow-elevated));
      background-color: var(--af-shade-card);
      transform: translateY(var(--af-motion-lift));
    }
  }
}

@layer components {
  .af-appearance-scope {
    color: var(--foreground);
    background-color: var(--background);
    font-family: var(--font-manrope, "Manrope"), system-ui, sans-serif;
  }

  .af-gradient-text {
    color: var(--primary);
    background-image: var(--af-gradient-text);
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  .af-gradient-border {
    border-color: color-mix(in srgb, var(--primary) 40%, var(--border));
    box-shadow: inset 0 1px 0 color-mix(in srgb, var(--primary) 18%, transparent);
  }

  .af-card {
    --tw-shadow: var(--af-card-shadow, var(--af-shadow-soft));
    background-color: var(--af-card-background, var(--surface));
    background-image: var(--af-card-image, none);
    -webkit-backdrop-filter: var(--af-card-blur, none);
    backdrop-filter: var(--af-card-blur, none);
    border-radius: var(--af-radius, 16px);
    transition:
      border-color var(--af-motion-hover) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing),
      background-color var(--af-motion-fast) var(--af-motion-easing);
  }

  .af-card-flat {
    --af-card-background: var(--surface);
    --af-card-image: none;
    --af-card-shadow: 0 0 #0000;
    --af-card-blur: none;
  }
  .af-card-elevated {
    --af-card-background: var(--surface);
    --af-card-image: none;
    --af-card-shadow: var(--af-shadow-elevated);
    --af-card-blur: none;
  }
  .af-card-glass {
    --af-card-background: var(--af-glass-background);
    --af-card-image: linear-gradient(130deg, color-mix(in srgb, var(--primary) 8%, transparent), transparent 65%);
    --af-card-shadow: var(--af-shadow-soft);
    --af-card-blur: blur(var(--af-glass-blur));
    border-color: color-mix(in srgb, var(--primary) 30%, var(--border));
  }
  .af-card-gradient {
    --af-card-background: var(--surface);
    --af-card-image: linear-gradient(135deg, var(--surface) 25%, color-mix(in srgb, var(--af-color-primary) 20%, var(--surface)));
    --af-card-shadow: var(--af-shadow-elevated);
    --af-card-blur: none;
    border-color: color-mix(in srgb, var(--primary) 30%, var(--border));
  }

  .af-control-solid { background-image: none; }
  .af-control-gradient {
    background-color: var(--primary);
    background-image: var(--af-gradient-primary);
    color: var(--primary-foreground);
    --tw-shadow: var(--af-shadow-soft);
  }
  .af-control-gradient:hover:not(:disabled,[data-disabled]) {
    --tw-shadow: var(--af-glow);
  }
  .af-control-soft {
    background-color: var(--accent);
    background-image: none;
    color: var(--accent-foreground);
    border: 1px solid color-mix(in srgb, var(--primary) 24%, var(--border));
  }
  .af-control-outline {
    background-color: var(--surface);
    background-image: none;
    border: 1px solid color-mix(in srgb, var(--primary) 45%, var(--border));
    color: var(--foreground);
    --tw-shadow: 0 0 #0000;
  }
  .af-control-glass {
    background-color: var(--af-glass-background);
    background-image: linear-gradient(120deg, color-mix(in srgb, var(--primary) 10%, transparent), transparent);
    backdrop-filter: blur(var(--af-glass-blur));
    border: 1px solid color-mix(in srgb, var(--primary) 45%, var(--border));
    color: var(--foreground);
  }

  .af-badge-solid, .af-badge-gradient {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  .af-badge-gradient { background-image: var(--af-gradient-primary); }
  .af-badge-soft { background-color: var(--accent); color: var(--accent-foreground); }
  .af-badge-outline { background-color: transparent; color: var(--foreground); border: 1px solid var(--border); }
  .af-badge-glass { background-color: var(--af-glass-background); color: var(--foreground); border: 1px solid var(--border); backdrop-filter: blur(12px); }

  .af-button-destructive[data-appearance] {
    color: var(--destructive-foreground);
    background-color: var(--destructive);
    background-image: none;
    border-color: color-mix(in srgb, var(--destructive-foreground) 45%, var(--border));
  }
  .af-button[data-disabled], .af-button:disabled {
    background-image: none;
    backdrop-filter: none;
  }

  .af-input, .af-textarea {
    border-color: color-mix(in srgb, var(--muted-foreground) 48%, var(--surface));
  }
}

[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card),
[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card)::before,
[data-motion-level="off"] :where(.af-button,.af-hover-card,.af-hover-link,.af-card)::after {
  animation: none !important;
  transition: none !important;
  transform: none !important;
}

@media (prefers-reduced-motion: reduce) {
  .af-button,
  .af-button::before,
  .af-button::after,
  .af-button[aria-busy="true"] > svg,
  .af-hover-card,
  .af-hover-card::before,
  .af-hover-card::after,
  .af-hover-link,
  .af-hover-link::before,
  .af-hover-link::after {
    animation: none !important;
    transition: none !important;
    transform: none !important;
    translate: none !important;
  }
}
